import json

def merge_duplicates(classified_data):
    unique_records = {}
    for record in classified_data:
        key = record['id']  # Assuming 'id' is a unique identifier
        if key not in unique_records:
            unique_records[key] = record
        else:
            unique_records[key] = merge_records(unique_records[key], record)
    return list(unique_records.values())


def merge_records(existing, new):
    # Logic to merge records, e.g., combine fields
    existing['description'] += ' ' + new['description']
    return existing

