def receive_webhook(event):
    try:
        payload = json.loads(event['body'])  # Parse the incoming JSON payload
        if 'event_id' not in payload:
            raise ValueError('Missing event_id in payload')  # Validate payload structure
        return payload  # Return the parsed payload
    except json.JSONDecodeError:
        return {'error': 'Invalid JSON'}  # Handle JSON parsing errors
    except ValueError as e:
        return {'error': str(e)}  # Handle validation errors

result = receive_webhook({'body': '{"event_id": "12345"}'})

import re

def chunk_text(documents, chunk_size=500):
    chunks = []  # List to hold text chunks
    for document in documents:
        text = re.split(r'(?<=[.!?]) +', document)  # Split by sentence
        for sentence in text:
            if len(sentence) > chunk_size:
                chunks.append(sentence[:chunk_size])  # Limit chunk size
            else:
                chunks.append(sentence)  # Append sentence as chunk
    return chunks

chunks = chunk_text(documents)

result = chunk_text()

