import json

def extract_themes(analyzed_feedback):
    themes = {}
    for record in analyzed_feedback:
        sentiment = record['sentiment']
        if sentiment > 0.5:
            theme = 'Positive'
        elif sentiment < -0.5:
            theme = 'Negative'
        else:
            theme = 'Neutral'
        if theme not in themes:
            themes[theme] = []
        themes[theme].append(record['text'])
    return themes

actionable_themes = extract_themes(analyzed_feedback)

result = extract_themes()

