def categorize_pull_requests(pull_requests):
    categories = {'features': [], 'fixes': [], 'internal': []}
    for pr in pull_requests:
        if 'feature' in pr['title'].lower():
            categories['features'].append(pr)
        elif 'fix' in pr['title'].lower():
            categories['fixes'].append(pr)
        else:
            categories['internal'].append(pr)
    return categories

