def apply_policy_rules(events):
    policy_rules = {
        'refund': lambda e: e['amount'] < 10000,
        'dispute': lambda e: e['reason'] != 'fraudulent'
    }
    eligible_events = []
    for event in events:
        event_type = event['type'].split('.')[1]
        if policy_rules[event_type](event['data']['object']):
            eligible_events.append(event)
    return eligible_events

filtered_events = apply_policy_rules(refund_events)
print(filtered_events)

