import traceback

def log_error(exception):
    error_data = {
        'message': str(exception),
        'level': 'error',
        'exception': {
            'values': [
                {'type': type(exception).__name__, 'value': str(exception), 'stacktrace': {'frames': traceback.extract_stack()}}
            ]
        }
    }
    send_error_to_sentry(error_data)

result = log_error()

